import { CommonModule } from '@angular/common';
import { Component, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { RouterModule } from '@angular/router';
import {
  IonButton,
  IonButtons,
  IonContent,
  IonHeader,
  IonIcon,
  IonMenuToggle,
  IonTitle,
  IonToolbar,
  ViewWillEnter,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { searchOutline } from 'ionicons/icons';
import { map, shareReplay, Subject, switchMap, tap } from 'rxjs';
import { getRoutePath, searchRoutePath } from '../app.routes';
import { AlertService } from '../common/alert/alert.service';
import { LoadingService } from '../common/loading/loading.service';
import { MenuToggleComponent } from '../common/menu/menu-toggle.component';
import { SkeletonCardComponent } from '../common/verse/skeleton-card/skeleton-card.component';
import { EmptyComponent } from '../favorites/empty/empty.component';
import { NoteAttachment } from '../verse/attachment';
import { NoteAttachmentCardComponent } from '../verse/note-attachment-card/note-attachment-card.component';
import { NotesService, NoteWithVerse } from './notes.service';

@Component({
  selector: 'app-notes',
  templateUrl: './notes.page.html',
  styleUrls: ['./notes.page.scss'],
  imports: [
    IonButton,
    IonButtons,
    IonContent,
    IonHeader,
    IonIcon,
    IonTitle,
    IonToolbar,
    CommonModule,
    FormsModule,
    EmptyComponent,
    SkeletonCardComponent,
    IonMenuToggle,
    MenuToggleComponent,
    NoteAttachmentCardComponent,
    RouterModule,
  ],
})
export class NotesPage implements ViewWillEnter {
  private refresh$ = new Subject<void>();
  private readonly alertService = inject(AlertService);
  private readonly notesService = inject(NotesService);
  private readonly loadingService = inject(LoadingService);

  readonly searchRouterLink = [getRoutePath(searchRoutePath)];

  notes$ = this.refresh$.pipe(
    switchMap(() => this.notesService.getNotesWithVerse()),
    map((notes) => notes.map((note) => this.createAttachment(note))),
    tap(() => this.loadingService.setLoading(false)),
    shareReplay(1)
  );

  constructor() {
    addIcons({ searchOutline });
  }

  ionViewWillEnter(): void {
    this.refresh$.next();
  }

  async removeNote(note: NoteAttachment) {
    try {
      await this.notesService.deleteNote(note.id);
    } catch (error) {
      await this.alertService.createNotice({
        message: 'Failed to delete note',
        duration: 5000,
        positionAnchor: 'footer',
      });
    } finally {
      this.loadingService.setLoading(true);
      this.refresh$.next();
    }
  }

  private createAttachment(note: NoteWithVerse) {
    const book = note.verses.book;
    const chapter = note.verses.chapter;
    const startVerse = note.verses.start_verse;
    const endVerse = note.verses.end_verse;
    const title = `${book} ${chapter}:${startVerse}${
      endVerse !== startVerse ? `-${endVerse}` : ''
    }`;
    return {
      ...note,
      title,
      type: 'Note',
      routerLink: ['verse', `${note.verses.id}`],
    } as NoteAttachmentCard;
  }
}

type NoteAttachmentCard = NoteAttachment & {
  title: string;
  routerLink: string[];
};
